fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since a and b have the same length, we can iterate by index.
    // For each index i, perform bitwise OR on a[i] and b[i].
    let mut result = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        result.push(a[i] | b[i]);
    }
    result
}